import {StoryboardSchema,type Storyboard,type Narration,type Shot} from '../core/schemas.js';
import {validateNarration} from '../story/timeline.js';
import {hash} from '../core/utils.js';

export const hasOriginalSource=(shot:Shot)=>!!shot.cinematic?.sourceWorld||!!shot.cinematic?.sourceOwnership?.length||[shot.cinematic?.performance,...(shot.cinematic?.actorScene?.supporting.map(a=>a.performance)??[])].some(p=>p?.sourceManipulation);

/** Membership alone is insufficient: a fragment cannot declare its own
 * truncated history authoritative. This structural gate covers the actual
 * complete narration clock; later validators establish original runs/cast/art. */
export function assertOriginalAuditContext(board:Storyboard,narration:Narration,fragments:readonly Shot[]):void{
  StoryboardSchema.parse(board);validateNarration(narration);
  if(new Set(board.shots.map(s=>s.id)).size!==board.shots.length||!board.shots.some(hasOriginalSource))
    throw new Error('needs-source-prop-binding: candidate audit requires a unique complete original storyboard');
  let cursor=0;
  for(const shot of board.shots){
    if(shot.startMs!==cursor||shot.endMs<=shot.startMs||shot.endMs>narration.durationMs)
      throw new Error('needs-source-prop-binding: candidate audit storyboard does not cover the complete narration clock');
    cursor=shot.endMs;
  }
  if(cursor!==narration.durationMs||!fragments.length||new Set(fragments.map(s=>s.id)).size!==fragments.length||fragments.some(shot=>board.shots.filter(s=>s.id===shot.id&&hash(s)===hash(shot)).length!==1))
    throw new Error('needs-source-prop-binding: candidate audit fragments must be exact unique members of the complete original storyboard');
}

import {z} from 'zod';
import {StoryboardSchema,NarrationSchema,BeatSchema,CharacterBibleSchema,type Storyboard,type Narration,type Beat,type CharacterBible} from '../core/schemas.js';
import {ConfigSchema,type FactoryConfig} from '../core/config.js';
import {HostProfileSchema,HostRigSchema,type HostProfile,type HostRig} from '../host/schemas.js';
import {hash} from '../core/utils.js';
import {validateStoryboard} from '../storyboard/validate.js';
import {validateActorContinuity} from '../actors/model.js';
import {validateStoryActingCoverage,requireFinalStoryDirection} from './story-coverage.js';
import {validateSourceCandidateStoryboard} from '../explainer/storyboard.js';
import {inspectCastCameras} from './cast-camera.js';
import {validateModelContinuity} from './index.js';
import {assertOriginalAuditContext,hasOriginalSource} from './source-audit-context.js';

export const SOURCE_PRODUCTION_AUDIT_VERSION='original-source-audit-1';
export interface SourceProductionAuditInput {
  board:Storyboard;narration:Narration;beats:Beat[];characters:CharacterBible;
  profile:HostProfile;rig:HostRig;config:FactoryConfig;
}
export interface SourceAuditCheck {
  id:string;shotId?:string;actorId?:string|null;
  status:'passed'|'failed'|'unavailable';message?:string;
}
export interface SourceProductionAudit {
  version:typeof SOURCE_PRODUCTION_AUDIT_VERSION;
  scope:'original-source-candidate-diagnostics';binding:Record<string,string>;fingerprint:string;
  sourceChecksPassed:boolean;checks:SourceAuditCheck[];
  pendingAcceptance:string[];
  productionBinding:'needs-source-prop-binding';canPublish:false;approved:false;
  productionReady:false;productionRig:null;availableBanks:[];motionVerified:false;productionApproval:false;
}

/** Read and clone before checking. Original scripts, cues, poses, artwork and
 * caller records are never edited, retimed, upgraded or approved here. Schema
 * failures remain failures, rather than a partial "passed" diagnostic. */
function sourceSnapshot(input:SourceProductionAuditInput):SourceProductionAuditInput{
  const copy=structuredClone(input);
  return {board:StoryboardSchema.parse(copy.board),narration:NarrationSchema.parse(copy.narration),beats:z.array(BeatSchema).parse(copy.beats),
    characters:CharacterBibleSchema.parse(copy.characters),profile:HostProfileSchema.parse(copy.profile),rig:HostRigSchema.parse(copy.rig),config:ConfigSchema.parse(copy.config)};
}

/** This deliberately executes existing semantic/physical validators only when
 * a human/test runtime requests diagnostics. It does not run providers, render
 * scenes/media, save artifacts, issue approval or substitute for final QC. */
export function inspectSourceProductionCandidate(input:SourceProductionAuditInput):SourceProductionAudit{
  const {board,narration,beats,characters,profile,rig,config}=sourceSnapshot(input);
  if(!board.shots.some(hasOriginalSource))
    throw new Error('needs-source-prop-binding: source audit requires an explicit original world, ownership or manipulation');
  if(config.content.mode!=='narrated-explainer'||config.presentation.mode!=='story-cinematic'||config.presentation.character_mode!=='actors'||(config.presentation.actor_renderer??'rig')!=='rig')
    throw new Error('needs-source-prop-binding: original source audit requires narrated story-cinematic rig actors');
  const binding={storyboard:hash(board),narration:hash(narration),beats:hash(beats),characters:hash(characters),profile:hash(profile),rig:hash(rig),
    // Only settings consumed by the validators. Provider credentials, commands
    // and voice defaults are outside this geometry/semantic diagnostic.
    settings:hash({content:config.content,presentation:config.presentation,topic:config.topic,final:config.rendering.final})};
  const report:SourceProductionAudit={version:SOURCE_PRODUCTION_AUDIT_VERSION,scope:'original-source-candidate-diagnostics',binding,fingerprint:hash({version:SOURCE_PRODUCTION_AUDIT_VERSION,binding}),sourceChecksPassed:false,checks:[],
    pendingAcceptance:['actual emitted SVG/GSAP, preflight versus renderer geometry/contact and seeking','faithful own native faces/hair/costumes/limbs/tool poses, vivid environment and film quality','rotating tools/canonical airborne ownership/changing depth contracts where required by the story','all story/script/WAV inputs, EN/VI/JA/KO and external/local TTS','resume/rebuild/locks and current MP4/audio/subtitle/thumbnail/review/final QC'],
    productionBinding:'needs-source-prop-binding',canPublish:false,approved:false,productionReady:false,productionRig:null,availableBanks:[],motionVerified:false,productionApproval:false};
  const check=(id:string,validate:()=>void,shotId?:string)=>{
    try{validate();report.checks.push({id,...(shotId?{shotId}:{}),status:'passed'});}
    catch(error){report.checks.push({id,...(shotId?{shotId}:{}),status:'failed',message:error instanceof Error?error.message:String(error)});}
  };
  check('storyboard-clock-source',()=>validateStoryboard(board,narration,beats,characters));
  check('complete-original-context',()=>assertOriginalAuditContext(board,narration,board.shots));
  check('actor-continuity',()=>validateActorContinuity(board));
  check('story-acting-coverage',()=>validateStoryActingCoverage(board,beats,narration));
  check('final-direction-source',()=>requireFinalStoryDirection(board,beats));
  for(const [index,shot] of board.shots.entries()){
    check('model-continuity',()=>validateModelContinuity(board.shots[index-1],shot,board,narration),shot.id);
    check('explainer-original-candidate',()=>{validateSourceCandidateStoryboard({shots:[shot]},narration,beats,profile,rig,config,board);},shot.id);
    // A source/art failure in one checker must not erase camera findings for
    // other actual people. The camera checker itself names dependency failures.
    try{
      const cameras=inspectCastCameras(shot,profile,board,narration);
      for(const row of cameras.actors)report.checks.push({id:'cast-camera',shotId:shot.id,actorId:row.actorId,status:'passed'});
      for(const issue of cameras.issues)report.checks.push({id:'cast-camera',shotId:shot.id,actorId:issue.actorId,status:issue.type==='camera-source'?'unavailable':'failed',message:issue.message});
      const scene=shot.cinematic?.actorScene,actual=[...(scene?.primary?[scene.primary.id]:[]),...(scene?.supporting.map(a=>a.character.id)??[])];
      for(const actorId of actual)if(!cameras.actors.some(row=>row.actorId===actorId)&&!cameras.issues.some(row=>row.actorId===actorId))
        report.checks.push({id:'cast-camera',shotId:shot.id,actorId,status:'unavailable',message:'Original world/source dependency prevented inspection of this actual actor'});
      if(!cameras.actors.length&&!cameras.issues.length)report.checks.push({id:'cast-camera',shotId:shot.id,status:'unavailable',message:'No actual camera subject was inspected'});
    }catch(error){report.checks.push({id:'cast-camera',shotId:shot.id,status:'unavailable',message:error instanceof Error?error.message:String(error)});}
  }
  report.sourceChecksPassed=report.checks.length>0&&report.checks.every(c=>c.status==='passed');
  return report;
}

export const sourceProductionAuditDescription={version:SOURCE_PRODUCTION_AUDIT_VERSION,
  scope:'read-only explicit original source candidate; complete storyboard/narration/beat/cast/settings snapshot; same semantic, physical, acting and camera validators; per-group issues survive production acceptance blockers',
  receipt:'diagnostic fingerprint only; not a scene/review/final/approval receipt; no source migration, providers, assets or media produced',
  productionBinding:'needs-source-prop-binding',canPublish:false,approved:false,productionReady:false,productionRig:null,availableBanks:[],motionVerified:false,productionApproval:false};

import {promises as fs} from 'node:fs';
import path from 'node:path';
import {loadConfig} from '../../packages/core/config.js';
import {loadHost} from '../../packages/host/index.js';
import {HostProfileSchema,HostRigSchema} from '../../packages/host/schemas.js';
import {hash} from '../../packages/core/utils.js';
import {inspectSourceProductionCandidate,type SourceProductionAuditInput} from '../../packages/director/source-production-audit.js';
import {ApiError,boundPath,redact} from './security.js';

const MAX_ARTIFACT_BYTES=4*1024*1024;
const required=['storyboard.json','beats.json','character-bible.json','host-profile.json','host-rig.json'] as const;

/** Exact source bytes, including the preferred voiced-narration selection.
 * This route is diagnostic, read-only, with no provider or production job. */
async function sourceFiles(root:string){
  const read=async(file:string,optional=false)=>{
    try{
      const absolute=await boundPath(root,'work/'+file),handle=await fs.open(absolute,'r');
      try{const stat=await handle.stat();if(!stat.isFile()||stat.size>MAX_ARTIFACT_BYTES)throw new ApiError(413,'Source audit artifact exceeds its bounded size.','SOURCE_AUDIT_TOO_LARGE');
        const bytes=await handle.readFile();if(bytes.length>MAX_ARTIFACT_BYTES)throw new ApiError(413,'Source audit artifact exceeds its bounded size.','SOURCE_AUDIT_TOO_LARGE');return bytes;
      }finally{await handle.close();}
    }catch(error){if((error as NodeJS.ErrnoException).code==='ENOENT'||error instanceof ApiError&&error.code==='NOT_FOUND'){if(optional)return null;throw new ApiError(409,'Create narration, analysis, host and storyboard artifacts before source audit.','SOURCE_AUDIT_CONTEXT_MISSING');}throw error;}
  };
  const voiced=await read('voiced-narration.json',true),narrationFile=voiced?'voiced-narration.json':'narration.json';
  const files=Object.fromEntries(await Promise.all(required.map(async file=>[file,(await read(file))!])));
  files[narrationFile]=voiced??(await read(narrationFile))!;
  return {files,narrationFile,receipts:Object.fromEntries(Object.entries(files).map(([file,bytes])=>['work/'+file,hash(bytes)]))};
}

export async function readSourceProductionAudit(root:string){
  const before=await sourceFiles(root),config=await loadConfig(root),host=await loadHost(root);
  // Bind the host that loadHost actually verified to the snapshot used below.
  const json=(file:string)=>{try{return JSON.parse(before.files[file]!.toString('utf8'));}catch{throw new ApiError(422,'Source audit input is not valid JSON.','SOURCE_AUDIT_INVALID');}};
  const profile=HostProfileSchema.parse(json('host-profile.json')),rig=HostRigSchema.parse(json('host-rig.json'));
  if(hash(host.profile)!==hash(profile)||hash(host.rig)!==hash(rig))throw new ApiError(409,'Source changed while preparing its audit. Reload and audit again.','SOURCE_AUDIT_STALE');
  const input={board:json('storyboard.json'),narration:json(before.narrationFile),beats:json('beats.json'),characters:json('character-bible.json'),profile,rig,config} as SourceProductionAuditInput;
  let report:ReturnType<typeof inspectSourceProductionCandidate>;
  try{report=inspectSourceProductionCandidate(input);}catch(error){throw new ApiError(422,redact(error instanceof Error?error.message:String(error)),'SOURCE_AUDIT_INVALID');}
  const [after,currentConfig,currentHost]=await Promise.all([sourceFiles(root),loadConfig(root),loadHost(root)]);
  if(before.narrationFile!==after.narrationFile||hash(before.receipts)!==hash(after.receipts)||hash(config)!==hash(currentConfig)||hash(host)!==hash(currentHost))
    throw new ApiError(409,'Source changed during audit. Reload and audit the current revision.','SOURCE_AUDIT_STALE');
  return {...report,checks:report.checks.map(check=>({...check,...(check.message?{message:redact(check.message)}:{})})),
    fileReceipts:before.receipts,narrationFile:'work/'+before.narrationFile,revisionChecked:true as const,
    freshness:'optimistic end-of-read comparison; not an OS snapshot, asset/audio receipt or publication authority' as const};
}

import type {SourceProductionAuditDocument} from '../../server/contracts.js';

const escape=(value:unknown)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));

/** Presentation only: no provider, source repair, approval or publication. */
export function sourceAuditMarkup(report:SourceProductionAuditDocument,locale:'vi'|'en'):string{
  const text=(vi:string,en:string)=>locale==='vi'?vi:en,issues=report.checks.filter(c=>c.status!=='passed');
  const status=(value:string)=>value==='failed'?text('Chưa đạt','Failed'):text('Chưa kiểm tra được','Unavailable');
  return `<section><h2 id="modal-title">${text('Kiểm tra cảnh','Scene checks')}</h2>
    <p>${report.sourceChecksPassed?text('Các quy tắc cảnh đã đạt. Video vẫn cần kiểm tra hình ảnh, chuyển động và âm thanh.', 'Scene rules passed. The video still needs visual, motion and audio review.'):text('Còn lỗi cần xử lý trước khi dựng video.', 'Issues remain before video production.')}</p>
    <p>${escape(report.checks.filter(c=>c.status==='passed').length)} / ${escape(report.checks.length)} ${text('mục kiểm tra đạt','checks passed')}. ${text('Xuất bản chưa được duyệt.','Publication is not approved.')}</p>
    ${issues.length?`<table><thead><tr><th>${text('Cảnh / Diễn viên','Scene / Actor')}</th><th>${text('Trạng thái','Status')}</th><th>${text('Cần xử lý','Issue')}</th></tr></thead><tbody>${issues.map(c=>`<tr><td>${escape([c.shotId,c.actorId].filter(Boolean).join(' / ')||text('Toàn câu chuyện','Whole story'))}</td><td>${escape(status(c.status))}</td><td>${escape(c.message||c.id)}</td></tr>`).join('')}</tbody></table>`:''}
    <p>${text('Cần model test nghiệm thu: diễn xuất và góc quay thực tế; nét vẽ và màu sắc theo mẫu; đồng bộ lời kể; cả ba đầu vào; tiếp tục và dựng lại; video cuối cùng và QC.', 'Test-model acceptance remains: actual acting and cameras; reference artwork and colors; narration synchronization; all three inputs; resume and rebuild; final video and QC.')}</p>
    <details><summary>${text('Dữ liệu cho model test','Data for the test model')}</summary><pre>${escape(JSON.stringify(report,null,2))}</pre></details>
    <footer><button type="button" data-action="close-modal">${text('Đóng','Close')}</button></footer></section>`;
}

import path from 'node:path';
import type { FactoryConfig } from '../core/config.js';
import { ShotSchema, type Beat, type Narration, type Shot, type Storyboard } from '../core/schemas.js';
